from sympy import Rational, expand, symbols, subresultants
from sympy.polys.subresultants_qq_zz import subresultants_pg, modified_subresultants_pg, modified_subresultants_sylv
x = symbols('x')
cases = [
    (4*x**3 + 3*x**2 + x + 2, x + 1),
    (x**4 - 1, x**2 - 1),
    (expand((x + 1)*(x**3 + 2*x + 3)), expand((x + 1)*(x**2 + x + 1))),
    (expand((x**2 + 1)*(x**4 - x + 2)), expand((x**2 + 1)*(x**2 + 2))),
    (x**2 + 1, x**2 + 1),
]
count = 0
for p, q in cases:
    for a, b in [(1, 1), (-1, 1), (1, -1), (-1, -1), (Rational(2, 3), Rational(-3, 5))]:
        f, g = expand(a*p), expand(b*q)
        for f, g in [(f, g), (g, f)]:
            assert subresultants_pg(f, g, x) == subresultants(f, g, x), (f, g)
            assert modified_subresultants_pg(f, g, x) == modified_subresultants_sylv(f, g, x), (f, g)
            count += 1
print('Passed', count, 'common-factor cases for both Pell-Gordon variants')
PY","yield_time_ms":1000,"max_output_tokens":2000}));
